const fs = await import('node:fs/promises');
const P2 = "D:\\GitHub\\My-second-brain\\50-知识\\AI工具";

// 国内 52 个（从已生成的书签提取，保证与报告一致）
const bmCN = await fs.readFile(P2+"\\服务大学生平台书签-52个.html","utf8");
const cnEntries = [...bmCN.matchAll(/<DT><A HREF="https:\/\/([^"]+)">([^<]+)<\/A>/g)].map(m=>({host:m[1], label:m[2]}));

// 海外 46 个
const bmOV = await fs.readFile(P2+"\\海外服务大学生书签-46个.html","utf8");
const ovEntries = [...bmOV.matchAll(/<DT><A HREF="https:\/\/([^"]+)">([^<]+)<\/A>/g)].map(m=>({host:m[1], label:m[2]}));

// 找重复（出现在两份里的）
const cnHosts = new Map(cnEntries.map(e=>[e.host, e.label]));
const dupes = [];
const ovUnique = [];
for (const e of ovEntries) {
  if (cnHosts.has(e.host)) dupes.push(e.host+" | 国内:"+cnHosts.get(e.host)+" / 海外:"+e.label);
  else ovUnique.push(e);
}
return { cn: cnEntries.length, ov: ovEntries.length, dupes, mergedTotal: cnEntries.length + ovUnique.length };
